import com.wuweibi.module4j.SupperModuleimport com.wuweibi.module4j.module.ModuleContextimport org.marker.mushroom.beans.Menuimport org.marker.mushroom.ext.menu.MenuUtilsimport org.marker.mushroom.ext.plugin.PluginContextimport org.marker.mushroom.ext.plugin.Pluginletimport org.marker.mushroom.utils.SpringUtilsimport org.marker.weixin.HandleMessageAdapterimport org.marker.weixin.DefaultSession/** * 盘查模块 *  * @author marker *  */public class PanchaModule2ActivatorImpl extends SupperModule {		/**	 * 启动模块	 * @param context	 * @param module	 * @throws Exception	 */	public void start(ModuleContext context ) throws Exception {		Class<?> wechatMessageListenerClass = require("PanchaAutoReplayHandleMessageListener");		if(null != wechatMessageListenerClass){			HandleMessageAdapter handleMessageAdapter = (HandleMessageAdapter)wechatMessageListenerClass.newInstance();			SpringUtils.autowireBean(handleMessageAdapter);			DefaultSession defaultSession = SpringUtils.getBean(DefaultSession.class);			defaultSession.addOnHandleMessageListener(handleMessageAdapter);		}		Class<?> clzz = require("PanchaPluginlet"); 		if(null != clzz){			PluginContext pluginContext = PluginContext.getInstance();			pluginContext.put((Pluginlet)clzz.newInstance());			Menu menu = new Menu();			menu.setIcon("fa-comments-o");			menu.setName("盘查管理");			menu.setUrl("/plugin/pancha/list.do");			menu.setModuleId(module.getId());// 模块ID			menu.setSort(1000)			MenuUtils menuUtils = MenuUtils.getInstance();			menuUtils.builder("bb2bc5fb802544a2a4634013d2c19936", menu );		}else{            logger.error("插件加载失败", module.getConfig());		}        // 加载插件标签					} 	public void stop(ModuleContext context) throws Exception {		MenuUtils menuUtils = MenuUtils.getInstance();		menuUtils.remove(this.id);	}}